// _variant_sizeCodecToken returns the length of the encoding of the codec.Token
// that x points at, and 1 when x fails to encode itself, so that the value is
// present and its encode reports the failure.
func _variant_sizeCodecToken(x *codec.Token) int {
	var scratch [128]byte
	enc, err := x.AppendBinary(scratch[:0])
	if err != nil {
		return 1
	}
	return len(enc)
}

// _variant_putAny9 writes the encoding of x, a any, into the end of buf, which
// has room for it, and returns its length. It fails for a value that fails to
// encode, which loc and num locate.
func _variant_putAny9(buf []byte, x any, loc string, num int) (int, error) {
	i := len(buf)
	switch x := x.(type) {
	case *int32:
		i -= _variant_putPtrInt32(buf[:i], x)
		i = wire.PutUvarint(buf, i, 1)
	case **int32:
		i -= _variant_putPtrPtrInt32(buf[:i], x)
		i = wire.PutUvarint(buf, i, 2)
	default:
		return 0, wire.UnlistedError(x, loc, num)
	}
	return len(buf) - i, nil
}

// _variant_putCodecToken writes the encoding of the codec.Token that x points
// at into the end of buf, which has room for it, and returns its length. It
// fails when x fails to encode itself.
func _variant_putCodecToken(buf []byte, x *codec.Token, loc string, num int) (int, error) {
	var scratch [128]byte
	enc, err := x.AppendBinary(scratch[:0])
	if err != nil {
		return 0, wire.MarshalError(err, loc, num)
	}
	return copy(buf[len(buf)-len(enc):], enc), nil
}

