// _variant_putPtrInt32 writes the encoding of x, a *int32, into the end of buf,
// which has room for it, and returns its length.
func _variant_putPtrInt32(buf []byte, x *int32) int {
	i := len(buf)
	if x != nil {
		i = wire.PutUvarint(buf, i, wire.Zigzag(int64(*x)))
	}
	i = wire.PutBool(buf, i, x != nil)
	return len(buf) - i
}

// _variant_putPtrPtrInt32 writes the encoding of x, a **int32, into the end of
// buf, which has room for it, and returns its length.
func _variant_putPtrPtrInt32(buf []byte, x **int32) int {
	i := len(buf)
	if x != nil {
		i -= _variant_putPtrInt32(buf[:i], *x)
	}
	i = wire.PutBool(buf, i, x != nil)
	return len(buf) - i
}

// _variant_putSliceInt32 writes the encoding of x, a []int32, into the end of
// buf, which has room for it, and returns its length.
func _variant_putSliceInt32(buf []byte, x []int32) int {
	i := len(buf)
	for k := len(x) - 1; k >= 0; k-- {
		i = wire.PutUvarint(buf, i, wire.Zigzag(int64(x[k])))
	}
	i = wire.PutUvarint(buf, i, uint64(len(buf)-i))
	return len(buf) - i
}

// _variant_putMapStringInt32 writes the encoding of x, a map[string]int32, into
// the end of buf, which has room for it, and returns its length.
func _variant_putMapStringInt32(buf []byte, x map[string]int32) int {
	i := len(buf)
	if len(x) <= 16 {
		type pair = wire.Pair[string, int32]
		var arr [16]pair
		pairs := arr[:0]
		for mk, mv := range x {
			pairs = append(pairs, pair{Key: mk, Value: mv})
		}
		wire.SortPairs(pairs)
		for k := len(pairs) - 1; k >= 0; k-- {
			i = wire.PutUvarint(buf, i, wire.Zigzag(int64(pairs[k].Value)))
			i = wire.PutRaw(buf, i, pairs[k].Key)
			i = wire.PutUvarint(buf, i, uint64(len(pairs[k].Key)))
		}
	} else {
		keys := make([]string, 0, len(x))
		for mk := range x {
			keys = append(keys, mk)
		}
		slices.Sort(keys)
		for k := len(keys) - 1; k >= 0; k-- {
			mk := keys[k]
			mv := x[mk]
			i = wire.PutUvarint(buf, i, wire.Zigzag(int64(mv)))
			i = wire.PutRaw(buf, i, mk)
			i = wire.PutUvarint(buf, i, uint64(len(mk)))
		}
	}
	i = wire.PutUvarint(buf, i, uint64(len(buf)-i))
	return len(buf) - i
}

// _variant_putGrid writes the encoding of x, a Grid, into the end of buf, which
