// _variant_putMapStringPtrSquare writes the encoding of x, a
// map[string]*Square, into the end of buf, which has room for it, and returns
// its length.
func _variant_putMapStringPtrSquare(buf []byte, x map[string]*Square) int {
	i := len(buf)
	if len(x) <= 16 {
		type pair = wire.Pair[string, *Square]
		var arr [16]pair
		pairs := arr[:0]
		for mk, mv := range x {
			pairs = append(pairs, pair{Key: mk, Value: mv})
		}
		wire.SortPairs(pairs)
		for k := len(pairs) - 1; k >= 0; k-- {
			i -= _variant_putPtrSquare(buf[:i], pairs[k].Value)
			i = wire.PutRaw(buf, i, pairs[k].Key)
			i = wire.PutUvarint(buf, i, uint64(len(pairs[k].Key)))
		}
	} else {
		keys := make([]string, 0, len(x))
		for mk := range x {
			keys = append(keys, mk)
		}
		slices.Sort(keys)
		for k := len(keys) - 1; k >= 0; k-- {
			mk := keys[k]
			mv := x[mk]
			i -= _variant_putPtrSquare(buf[:i], mv)
			i = wire.PutRaw(buf, i, mk)
			i = wire.PutUvarint(buf, i, uint64(len(mk)))
		}
	}
	i = wire.PutUvarint(buf, i, uint64(len(buf)-i))
	return len(buf) - i
}

// _variant_putSliceSquare writes the encoding of x, a []Square, into the end of
// buf, which has room for it, and returns its length.
func _variant_putSliceSquare(buf []byte, x []Square) int {
	i := len(buf)
	for k := len(x) - 1; k >= 0; k-- {
		w, _ := x[k].encodeKanon(buf[:i])
		i -= w
		i = wire.PutUvarint(buf, i, uint64(w))
	}
	i = wire.PutUvarint(buf, i, uint64(len(buf)-i))
	return len(buf) - i
}

// _variant_putMapStringSquare writes the encoding of x, a map[string]Square,
// into the end of buf, which has room for it, and returns its length.
func _variant_putMapStringSquare(buf []byte, x map[string]Square) int {
	i := len(buf)
	var arr [16]string
	keys := arr[:0]
	for mk := range x {
		keys = append(keys, mk)
	}
	slices.Sort(keys)
	for k := len(keys) - 1; k >= 0; k-- {
		mk := keys[k]
		mv := x[mk]
		{
			w, _ := mv.encodeKanon(buf[:i])
			i -= w
			i = wire.PutUvarint(buf, i, uint64(w))
		}
		i = wire.PutRaw(buf, i, mk)
		i = wire.PutUvarint(buf, i, uint64(len(mk)))
	}
	i = wire.PutUvarint(buf, i, uint64(len(buf)-i))
	return len(buf) - i
}

// _variant_putCodecWord writes the encoding of the codec.Word that x points at
// into the end of buf, which has room for it, and returns its length. It fails
// when x fails to encode itself.
func _variant_putCodecWord(buf []byte, x *codec.Word, loc string, num int) (int, error) {
	enc, err := x.MarshalText()
	if err != nil {
		return 0, wire.MarshalError(err, loc, num)
	}
	return copy(buf[len(buf)-len(enc):], enc), nil
}

// _variant_putPtrCodecStamp writes the encoding of x, a *codec.Stamp, into the
// end of buf, which has room for it, and returns its length. It fails for a
// value that fails to encode, which loc and num locate.
func _variant_putPtrCodecStamp(buf []byte, x *codec.Stamp, loc string, num int) (int, error) {
	i := len(buf)
	if x != nil {
		w, err := _variant_putCodecStamp(buf[:i], x, loc, num)
		if err != nil {
			return 0, err
		}
		i -= w
		i = wire.PutUvarint(buf, i, uint64(w))
	}
	i = wire.PutBool(buf, i, x != nil)
	return len(buf) - i, nil
}

// _variant_putExternalCode writes the encoding of the external.Code that x
// points at into the end of buf, which has room for it, and returns its length.
// It fails when x fails to encode itself.
func _variant_putExternalCode(buf []byte, x *external.Code, loc string, num int) (int, error) {
	enc, err := x.MarshalBinary()
	if err != nil {
		return 0, wire.MarshalError(err, loc, num)
	}
	return copy(buf[len(buf)-len(enc):], enc), nil
}

// _variant_putPtrSquare writes the encoding of x, a *Square, into the end of
// buf, which has room for it, and returns its length.
func _variant_putPtrSquare(buf []byte, x *Square) int {
	i := len(buf)
	if x != nil {
		w, _ := x.encodeKanon(buf[:i])
		i -= w
		i = wire.PutUvarint(buf, i, uint64(w))
	}
	i = wire.PutBool(buf, i, x != nil)
	return len(buf) - i
}

// _variant_putPatch writes the encoding of the Patch that m points at into the
// end of buf, which has room for it, and returns its length.
func _variant_putPatch(buf []byte, m *Patch) int {
	i := len(buf)
	if len(m.Cells) > 0 {
		i -= _variant_putSliceInt32(buf[:i], m.Cells)
		i = wire.PutTag(buf, i, 1<<3|wire.Bytes)
	}
	return len(buf) - i
}

// _variant_putExternalPairStringInt8 writes the encoding of the
// external.Pair[string, int8] that m points at into the end of buf, which has
// room for it, and returns its length.
func _variant_putExternalPairStringInt8(buf []byte, m *external.Pair[string, int8]) int {
	i := len(buf)
	if m.Val != 0 {
		i = wire.PutUvarint(buf, i, wire.Zigzag(int64(m.Val)))
		i = wire.PutTag(buf, i, 2<<3|wire.Varint)
	}
	if m.Key != "" {
		i = wire.PutRaw(buf, i, m.Key)
		i = wire.PutUvarint(buf, i, uint64(len(m.Key)))
		i = wire.PutTag(buf, i, 1<<3|wire.Bytes)
	}
	return len(buf) - i
}

// _variant_readPtrSquare decodes the *Square at the start of data into *dst and
// returns the length of its encoding: nil for the presence byte 0, and for the
// presence byte 1 the value that follows, into the value that *dst points at or
// into a new one. With merge set, the struct merges into the struct that *dst
// points at. data starts at offset off of slab, and the decode enters depth
// levels below the value at most. loc and num locate the field in errors.
func _variant_readPtrSquare(dst **Square, data []byte, slab string, off, depth int, merge bool, loc string, num int) (int, error) {
	if depth < 0 {
		return 0, wire.DepthError(loc, num, off)
	}
	present, err := wire.Presence(data, loc, num, off)
	if err != nil {
		return 0, err
	}
	if !present {
		*dst = nil
		return 1, nil
	}
	x := *dst
	if x == nil {
		x = new(Square)
		*dst = x
	}
	i := 1
	l, n := wire.Uvarint(data[i:])
	if n <= 0 || uint64(len(data)-i-n) < l {
		return 0, wire.ReadError(n, loc, num, off+i)
	}
	i += n
	if depth < 1 {
		return 0, wire.DepthError("Square", 0, off+i)
	}
	{
		var err error
		if merge {
			err = x.mergeKanon(data[i:i+int(l)], slab, off+i, depth-1)
		} else {
			err = x.decodeKanon(data[i:i+int(l)], slab, off+i, depth-1)
		}
		if err != nil {
			return 0, err
		}
	}
	i += int(l)
	return i, nil
}

// _variant_mergePatch merges the encoding in data, which starts at offset off
// of slab, into the Patch that m points at, as MergeKanon does. The decode
// enters depth levels below m at most.
func _variant_mergePatch(m *Patch, data []byte, slab string, off, depth int) error {
	for i := 0; i < len(data); {
		at := i
		tag, n := wire.Uvarint(data[i:])
		if n <= 0 {
			return wire.ReadError(n, "Patch", 0, off+i)
		}
		i += n
		switch tag >> 3 {
		case 1:
			if tag != 1<<3|wire.Bytes {
				return wire.FormatError(tag, wire.Bytes, "Patch.Cells", off+at)
			}
			l, n := wire.Uvarint(data[i:])
			if n <= 0 || uint64(len(data)-i-n) < l {
				return wire.ReadError(n, "Patch.Cells", 1, off+i)
			}
			i += n
			if err := _variant_readSliceInt32(&m.Cells, data[i:i+int(l)], slab, off+i, depth-1, "Patch.Cells", 1); err != nil {
				return err
			}
			i += int(l)
		default:
			n, err := wire.Skip(data[i:], tag, "Patch", 0, off+at)
			if err != nil {
				return err
			}
			i += n
		}
	}
	return nil
}

// _variant_readPatch sets the Patch that m points at to the value encoded in
// data and reuses its memory, as DecodeKanon does. data starts at offset off of
// slab, and the decode enters depth levels below the value at most.
func _variant_readPatch(m *Patch, data []byte, slab string, off, depth int) error {
	m.Cells = m.Cells[:0]
	return _variant_mergePatch(m, data, slab, off, depth)
}

// _variant_mergeVariantsStructsStruct merges the encoding in data, which starts
