// fails when x fails to encode itself.
func _variant_putCodecStamp(buf []byte, x *codec.Stamp, loc string, num int) (int, error) {
	var scratch [128]byte
	enc, err := x.AppendBinary(scratch[:0])
	if err != nil {
		return 0, wire.MarshalError(err, loc, num)
	}
	return copy(buf[len(buf)-len(enc):], enc), nil
}

// _variant_readArray2Int8 decodes the elements that data encodes, a [2]int8
// without its length, into *dst. It fails unless data encodes exactly 2
// elements. data starts at offset off of slab, and the decode enters depth
// levels below the value at most. loc and num locate the field in errors.
func _variant_readArray2Int8(dst *[2]int8, data []byte, slab string, off, depth int, loc string, num int) error {
	i := 0
	for k := range dst {
		u, n := wire.Uvarint(data[i:])
		if n <= 0 {
			return wire.ReadError(n, loc, num, off+i)
		}
		s := wire.Unzigzag(u)
		if s != int64(int8(s)) {
			return wire.RangeError(s, "int8", loc, num, off+i)
		}
		dst[k] = int8(s)
		i += n
	}
	if i != len(data) {
		return wire.TrailingError(len(data)-i, loc, num, off+i)
	}
	return nil
}

// _variant_readPtrCircle decodes the *Circle at the start of data into *dst and
// returns the length of its encoding: nil for the presence byte 0, and for the
// presence byte 1 the value that follows, into the value that *dst points at or
// into a new one. data starts at offset off of slab, and the decode enters
// depth levels below the value at most. loc and num locate the field in errors.
func _variant_readPtrCircle(dst **Circle, data []byte, slab string, off, depth int, loc string, num int) (int, error) {
	if depth < 0 {
		return 0, wire.DepthError(loc, num, off)
	}
	present, err := wire.Presence(data, loc, num, off)
	if err != nil {
		return 0, err
	}
	if !present {
		*dst = nil
		return 1, nil
	}
	x := *dst
	if x == nil {
		x = new(Circle)
		*dst = x
	}
	i := 1
	l, n := wire.Uvarint(data[i:])
	if n <= 0 || uint64(len(data)-i-n) < l {
		return 0, wire.ReadError(n, loc, num, off+i)
	}
	i += n
	if depth < 1 {
		return 0, wire.DepthError("Circle", 0, off+i)
	}
	if err := x.decodeKanon(data[i:i+int(l)], slab, off+i, depth-1); err != nil {
		return 0, err
	}
	i += int(l)
	return i, nil
}

// _variant_clonePtrCircle returns a pointer to a copy of the value that x, a
// *Circle, points at, and nil for a nil x.
func _variant_clonePtrCircle(x *Circle) *Circle {
	if x == nil {
		return nil
	}
	return new(*x)
}
